            if(i<n){pool.push_back(a[i+1]);len[sz+i]=1;Sum[sz+i]=a[i+1];}
            else {len[sz+i]=0;Sum[sz+i]=0;}
        }
        const ll NEG=LLONG_MIN/4;
        for(int u=sz-1;u>=1;u--){
            int lc=2*u,rc=2*u+1;
            ll SumA=Sum[lc];int offA=off[lc],a_=len[lc];int offB=off[rc],b_=len[rc];
            off[u]=(int)pool.size();int c=0,bb=0;
            while(c<a_||bb<b_){
                ll nextA=(c<a_)?pool[offA+c]:NEG;
                ll nextB=(bb<b_)?(pool[offB+bb]-(ll)c*p+SumA):NEG;
                if(nextA>=nextB){ll T=nextA;c++;int before=bb;
                    while(bb>=1&&(pool[offB+bb-1]-(ll)c*p+SumA)<T)bb--;
                    if(bb==before)pool.push_back(T);
                }else{ll T=nextB;bb++;pool.push_back(T);}
            }
            len[u]=(int)pool.size()-off[u];Sum[u]=SumA+Sum[rc];lo[u]=lo[lc];
        }
    }
    ll query(ll l,ll r,ll x){
        ll T=S[l-1]-x+p;ll k=0;
        int L=(int)(l-1)+sz,R=(int)(r-1)+sz;
        int lft[64],rgt[64],nl=0,nr=0;
        while(L<=R){if(L&1)lft[nl++]=L++;if(!(R&1))rgt[nr++]=R--;L>>=1;R>>=1;}
        for(int i=0;i<nl;i++){int u=lft[i];ll Trel=T-S[lo[u]];int a_=len[u];const ll* vp=pool.data()+off[u];
            int lo2=0,hi=a_;while(lo2<hi){int mid=(lo2+hi)>>1;if(vp[mid]>=Trel)lo2=mid+1;else hi=mid;}
            k+=lo2;T+=(ll)lo2*p;}
        for(int i=nr-1;i>=0;i--){int u=rgt[i];ll Trel=T-S[lo[u]];int a_=len[u];const ll* vp=pool.data()+off[u];
            int lo2=0,hi=a_;while(lo2<hi){int mid=(lo2+hi)>>1;if(vp[mid]>=Trel)lo2=mid+1;else hi=mid;}
            k+=lo2;T+=(ll)lo2*p;}
        return x+(S[r]-S[l-1])-k*p;
    }
};

ll brute(vector<ll>&a,int l,int r,ll x,ll p){
    ll s=x;for(int i=l;i<=r;i++){s+=a[i];if(s>=p)s-=p;}return s;
}

int main(){
    mt19937_64 rng(2024);
    for(int tc=0;tc<20000;tc++){
        int n=1+rng()%300;
        ll p=1+rng()%1000;
        vector<ll> a(n+1);
        for(int i=1;i<=n;i++){
            int t=rng()%4;
            if(t==0)a[i]=(ll)(rng()%2001)-1000;
            else if(t==1)a[i]=(ll)(rng()%2000000001ULL)-1000000000LL;
            else if(t==2)a[i]=(ll)(rng()%7)-3;
            else a[i]=(ll)(rng()%21)-10;
        }
        Solver sol; sol.init(n,p,a);
        // simulate online: we have actual queries (l,r,x), encode by xoring lastans
        ll lastans=0;
        int m=1+rng()%40;
        for(int q=0;q<m;q++){
            int l=1+rng()%n; int r=l+rng()%(n-l+1); ll x=rng()%p;
            ll el=l^lastans, er=r^lastans, ex=x^lastans;
            // solver reads el,er,ex and decodes
            ll dl=el^lastans, dr=er^lastans, dx=ex^lastans;
            if(dl!=l||dr!=r||dx!=x){printf("decode fail\n");return 0;}
            ll fs=sol.query(dl,dr,dx);
            ll bf=brute(a,l,r,x,p);
            if(fs!=bf){
                printf("MISMATCH tc=%d n=%d p=%lld\n",tc,n,p);
                printf("a:");for(int i=1;i<=n;i++)printf(" %lld",a[i]);printf("\n");
                printf("query l=%d r=%d x=%lld brute=%lld fast=%lld lastans=%lld\n",l,r,x,bf,fs,lastans);
                return 0;
            }
            ll ans=bf;
            lastans=((ans%n)+n)%n;
        }
    }
    printf("ALL OK\n");
    return 0;
}

