// number of wraps starting at value s over elements [l0+1 .. l0+L] (1-indexed l0=lo)
ll actualWraps(int start0, int L, ll s){
    ll k=0;
    for(int i=0;i<L;i++){
        ll ai=a[start0+1+i];
        if(s+ai>=p){ k++; s=s+ai-p; }
        else s=s+ai;
    }
    return k;
}

