// merge algorithm as in the code; A,B are decreasing arrays (thresholds)
vector<ll> mergeAlg(vector<ll> A, vector<ll> B, ll SumA, ll p){
    int a_=A.size(), b_=B.size();
    vector<ll> C;
    const ll NEG=LLONG_MIN/4;
    int c=0,bb=0;
    while(c<a_||bb<b_){
        ll nextA=(c<a_)?A[c]:NEG;
        ll nextB=(bb<b_)?(B[bb]-(ll)c*p+SumA):NEG;
        if(nextA>=nextB){
            ll T=nextA;c++;int before=bb;
            while(bb>=1 && (B[bb-1]-(ll)c*p+SumA)<T) bb--;
            if(bb==before) C.push_back(T);
        } else {
            ll T=nextB;bb++;C.push_back(T);
        }
    }
    return C;
}

