// compute valid threshold array for segment X (sum returned)
vector<ll> thresholds(vector<ll>&X, ll p, ll &sumOut){
    int m=X.size(); sumOut=0; for(ll x:X) sumOut+=x;
    // find s range: k=0 for very negative, k=m for very positive
    ll Amin=0,Amax=0,cur=0;
    ll mn=0,mx=0;
    for(ll x:X){cur+=x; mn=min(mn,cur); mx=max(mx,cur);}
    // wrap at step i needs s + (prefix before) + x_i >= p. threshold s >= p - prefix_i (i-th prefix)
    // we'll just scan s in [-(abs sum)-p-2, (abs sum)+p+2]
    ll R=0; for(ll x:X) R+=llabs(x); R+=p+5;
    vector<ll> v;
    ll prevk=-1;
    for(ll s=-R;s<=R;s++){
        // brute k over X
        ll k=0,cs=s;
        for(ll x:X){ if(cs+x>=p){k++;cs=cs+x-p;} else cs=cs+x; }
        if(prevk!=-1 && k>prevk){
            for(ll rep=prevk;rep<k;rep++) v.push_back(p-s);
        }
        prevk=k;
    }
    // v should be decreasing? thresholds as t=p-s increase as s decreases. We scanned s increasing => p-s decreasing, so pushes are decreasing. good.
    return v;
}

int main(){
    mt19937_64 rng(4242);
    for(int tc=0;tc<200000;tc++){
