        ll sumA,A_,B_;
        vector<ll> A=thresholds(X,p,sumA);
        vector<ll> B=thresholds(Y,p,B_);
        vector<ll> C=mergeAlg(A,B,sumA,p);
        // candidate s
        vector<ll> cand;
        cand.push_back(-1000000); cand.push_back(1000000);
        for(ll v:A){cand.push_back(p-v-1);cand.push_back(p-v);cand.push_back(p-v+1);}
        for(ll v:B){cand.push_back(p-v-1);cand.push_back(p-v);cand.push_back(p-v+1);}
        for(ll v:C){cand.push_back(p-v-1);cand.push_back(p-v);cand.push_back(p-v+1);}
        for(ll s:cand){
            ll kL=k_of(A,s,p);
            ll s2=s+sumA-kL*p;
            ll kR=k_of(B,s2,p);
            ll actual=kL+kR;
