#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> mergeAlg(vector<ll> A, vector<ll> B, ll SumA, ll p){
    int a_=A.size(), b_=B.size();
    vector<ll> C;
    const ll NEG=LLONG_MIN/4;
    int c=0,bb=0;
    while(c<a_||bb<b_){
        ll nextA=(c<a_)?A[c]:NEG;
        ll nextB=(bb<b_)?(B[bb]-(ll)c*p+SumA):NEG;
        if(nextA>=nextB){ll T=nextA;c++;int before=bb;
            while(bb>=1 && (B[bb-1]-(ll)c*p+SumA)<T) bb--;
            if(bb==before) C.push_back(T);
        } else {ll T=nextB;bb++;C.push_back(T);}
    }
    return C;
}
ll k_of(vector<ll>&v, ll s, ll p){ ll cnt=0; for(ll x:v) if(x>=p-s) cnt++; return cnt; }

vector<ll> thresholds(vector<ll>&X, ll p, ll &sumOut){
    int m=X.size(); sumOut=0; for(ll x:X) sumOut+=x;
    ll R=0; for(ll x:X) R+=llabs(x); R+=p+5;
    vector<ll> v; ll prevk=-1;
    for(ll s=-R;s<=R;s++){
        ll k=0,cs=s;
        for(ll x:X){ if(cs+x>=p){k++;cs=cs+x-p;} else cs=cs+x; }
        if(prevk!=-1 && k>prevk) for(ll rep=prevk;rep<k;rep++) v.push_back(p-s);
        prevk=k;
    }
    return v;
}

int main(){
    vector<ll> pal;
    for(ll x=-3;x<=3;x++) pal.push_back(x);
    // precompute threshold arrays for all X of length 1..3 for each p
    for(ll p=1;p<=6;p++){
        vector<pair<vector<ll>,ll>> segs; // thresholds, sum
        // enumerate arrays
        for(int L=1;L<=3;L++){
            long long tot=1; for(int i=0;i<L;i++) tot*=pal.size();
            for(long long mask=0;mask<tot;mask++){
                vector<ll> X(L); long long mm=mask;
                for(int i=0;i<L;i++){X[i]=pal[mm%pal.size()];mm/=pal.size();}
                ll sum; auto A=thresholds(X,p,sum);
                segs.push_back({A,sum});
            }
        }
        // test all pairs
        for(size_t i=0;i<segs.size();i++)for(size_t j=0;j<segs.size();j++){
            auto &A=segs[i].first; ll sumA=segs[i].second;
            auto &B=segs[j].first;
            auto C=mergeAlg(A,B,sumA,p);
            vector<ll> cand; cand.push_back(-1000000);cand.push_back(1000000);
            for(ll v:A){cand.push_back(p-v-1);cand.push_back(p-v);cand.push_back(p-v+1);}
            for(ll v:B){cand.push_back(p-v-1);cand.push_back(p-v);cand.push_back(p-v+1);}
